{
  "table": {
    "name": "badges",
    "purpose": "Badge awards on a Stack Exchange-style Q&A site: one row per badge granted to a user. The surrounding tables (users, posts, votes, comments, tags, postHistory, postLinks) are exactly the Stack Exchange data-dump schema, and the badge names (Student, Supporter, Editor, Scholar, Teacher, Autobiographer, Analytical) are canonical Stack Exchange badges. The tag-like names (correlation, nonparametric, modeling, pca) indicate tag badges for a statistics-oriented site (consistent with Cross Validated, stats.stackexchange.com). A user can earn the same badge multiple times; each award is its own row. Note the schema lacks the Class/TagBased columns of the official dump, so badge class must be inferred from the name if needed."
  },
  "columns": {
    "Date": {
      "role": "date",
      "name": "awarded_at",
      "description": "Timestamp (second precision) at which the badge was awarded to the user. Range 2010-07-19 to 2014-09-14, matching the site's lifetime in the dump. The single spike at 2014-07-02 16:05:34 (899 rows) reflects a bulk award/recalculation event on that date, not a different meaning; all other values are individually spread in time.",
      "status": "resolved"
    },
    "Id": {
      "role": "identifier",
      "name": "badge_award_id",
      "description": "Surrogate primary key uniquely identifying one badge-award row (1..92240, no gaps in distinctness). It identifies the award event, not the badge type (the type is Name) nor the user. The accepted joins from postLinks.LinkTypeId and posts.PostTypeId are coincidental numeric matches: those columns hold small type codes (roughly 1-3), which trivially match low badge Ids; they are not real relationships and should be ignored.",
      "status": "resolved"
    },
    "Name": {
      "role": "category",
      "name": "badge_name",
      "description": "Name of the badge awarded. 153 distinct values of two kinds: standard Stack Exchange achievement badges (Student, Supporter, Editor, Scholar, Teacher, Autobiographer, Analytical, ...) and tag badges named after the site's tags for sustained contributions in that topic (correlation, nonparametric, modeling, pca, ...). The tag-badge names double as entries in the tags table. This is the badge type, not a person name.",
      "status": "resolved"
    },
    "UserId": {
      "role": "foreign_key",
      "name": "user_id",
      "description": "Foreign key to users.Id: the user who received this badge. Many-to-one (79,851 awards across 25,078 users; the most-decorated user, Id 919, holds 456 badges). No nulls, so every award is tied to a known user.",
      "status": "resolved"
    }
  }
}
